import numpy as np
from collections import deque
A=np.load('source_pixels.npz')['rgb']
# differences from frame70 and prev
for typ in ['ref','prev']:
 print('\\n',typ)
 for t in range(0,61):
  ref=A[70] if typ=='ref' else A[max(0,t-1)]
  d=np.max(abs(A[t].astype(int)-ref.astype(int)),axis=2)
  m=d>12
  # components 8c
  seen=np.zeros_like(m); comps=[]
  for y,x in zip(*np.where(m&~seen)):
   if seen[y,x]:continue
   stack=[(y,x)];seen[y,x]=1; xs=[];ys=[]
   while stack:
    yy,xx=stack.pop();xs.append(xx);ys.append(yy)
    for dy in (-1,0,1):
     for dx in (-1,0,1):
      ny,nx=yy+dy,xx+dx
      if 0<=ny<144 and 0<=nx<256 and m[ny,nx] and not seen[ny,nx]:seen[ny,nx]=1;stack.append((ny,nx))
   if len(xs)>=5:comps.append((len(xs),min(xs),min(ys),max(xs),max(ys)))
  comps.sort(reverse=True)
  if t%2==0 or t<10:
   print(f'{t:02}', comps[:6])
PY
python .tmp/components.py"

